function guideHtml(){
  var nav='<div class="v19-chips">'+GUIDE.map(function(g,i){return '<button type="button" data-gi="'+i+'">'+esc(g.t)+'</button>'}).join('')+'<button type="button" data-gi="new">الجديد</button></div>';
  return nav+'<p class="v19-lead">لكل صفحة: صورتها من البرنامج، وكيف تصل إليها، وشرح أزرارها، وميزاتها، ومتى تستخدمها.</p>'+GUIDE.map(function(g,i){
    return '<section class="v19-g" id="v19g'+i+'"><h3><span class="n">'+(i+1)+'</span>'+esc(g.t)+'</h3><div class="v19-b"><img loading="lazy" alt="'+esc(g.t)+'" src="'+g.img+'"><div class="v19-tx"><div class="v19-where">📍 كيف أصل إليها: <b>'+esc(g.w)+'</b></div><p>'+esc(g.d)+'</p></div></div>'+
    (g.b.length?'<h5>الأزرار</h5><dl>'+g.b.map(function(x){return '<dt>'+esc(x[0])+'</dt><dd>'+esc(x[1])+'</dd>'}).join('')+'</dl>':'')+
    '<h5>المميزات</h5><ul>'+g.f.map(function(x){return '<li>'+x+'</li>'}).join('')+'</ul><h5>متى أستخدمها</h5><p>'+esc(g.u)+'</p></section>';
  }).join('')+'<section class="v19-g" id="v19gnew"><h3>الجديد في الإصدارات</h3>FEATSLOT</section>';
}
function openGuide(){
  var p=$('v19Page');
  if(!p){ p=document.createElement('div'); p.id='v19Page'; p.setAttribute('role','dialog'); p.setAttribute('aria-label','خواص البرنامج');
    p.innerHTML='<header><button type="button" id="v19Back" aria-label="رجوع">›</button><h2>خواص البرنامج</h2></header><div class="v19-sc" id="v19Sc">'+guideHtml().replace('FEATSLOT',featHtml())+'</div>';
    document.body.appendChild(p);
    $('v19Back').addEventListener('click',function(){ p.classList.remove('on'); });
    p.addEventListener('click',function(e){ var b=e.target.closest('[data-gi]'); if(!b) return; var t=$('v19g'+(b.dataset.gi==='new'?'new':b.dataset.gi)); setOn(b.dataset.gi); if(t) t.scrollIntoView({behavior:'smooth',block:'start'}); });
    var lock=0;
    function setOn(gi){ var all=qa('#v19Sc .v19-chips button'); all.forEach(function(x){ var on=x.dataset.gi===String(gi); x.classList.toggle('on',on); if(on){ x.setAttribute('aria-current','true'); try{ var c=x.parentNode; c.scrollTo({left:x.offsetLeft-c.clientWidth/2+x.offsetWidth/2,behavior:'smooth'}); }catch(e){} } else x.removeAttribute('aria-current'); }); lock=Date.now(); }
    var sc=$('v19Sc'); var cur=null;
    sc.addEventListener('scroll',function(){
      if(Date.now()-lock<700) return;
      var secs=qa('#v19Sc .v19-g'), pos=sc.scrollTop+90, id=null;
      secs.forEach(function(g){ if(g.offsetTop<=pos) id=g.id.replace('v19g',''); });
      if(id===null) id='0';
      if(id!==cur){ cur=id; setOn(id); lock=0; }
    },{passive:true});
    setOn('0'); lock=0;
  }
  var gb=$('settingsClose'); if($('settingsPanel')&&$('settingsPanel').classList.contains('open')&&gb) gb.click();
  p.classList.add('on'); $('v19Sc').scrollTop=0;
}
function featHtml(){
  /* v71: الإصدارات من الأحدث للأقدم (المجموعات العامة بلا إصدار تبقى أولًا) */
  var vn=function(g){return g.v?parseInt(String(g.v).replace(/\D/g,''),10)||0:-1};
  var sorted=FEATURES.map(function(g,i){return {g:g,i:i}}).sort(function(a,b){var x=vn(a.g),y=vn(b.g); if(x<0&&y<0) return a.i-b.i; if(x<0) return -1; if(y<0) return 1; return y-x||a.i-b.i}).map(function(o){return o.g});
  return sorted.map(function(g,i){
    var nw=g.v?'<span class="nw">'+esc(g.v)+'</span>':'';
    return '<details class="v14-feat"><summary>'+esc(g.g)+nw+'</summary><ul>'+g.items.map(function(x){return '<li>'+(g.v?x:esc(x))+'</li>'}).join('')+'</ul></details>';
  }).join('');
}
