  feat.innerHTML='<div class="settings-label">خواص البرنامج</div><button type="button" class="v19-open" id="v19Open"><span>📖 دليل الصفحات والأزرار<small>شرح مصوّر لكل صفحة + ما الجديد</small></span><b>‹</b></button>'; feat.addEventListener('click',function(e){ if(e.target.closest('#v19Open')) openGuide(); });
  var rs=$('settingsReset'); if(rs&&rs.parentNode===panel){ var th=$('themeAutoBtn'); th=th&&th.closest('.settings-section'); if(th) th.before(lay); else panel.insertBefore(lay,rs); panel.insertBefore(sec,rs); panel.insertBefore(feat,rs); } else { panel.appendChild(sec); panel.appendChild(feat); }
  $('v14Lay').addEventListener('click',function(e){ var b=e.target.closest('[data-l]'); if(!b) return; P.layout=b.dataset.l; save(); applyLayout(false); });
  qa('#v14Lay [data-l]').forEach(function(b){ b.classList.toggle('active',b.dataset.l===(P.layout||'classic')); });
  $('v14Sw').addEventListener('click',function(){ P.swipe=!P.swipe; save(); this.setAttribute('aria-checked',P.swipe?'true':'false'); });
